sp_HomeFaturamentoMensal	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_HomeFaturamentoMensal`(\nIN p_idEmpresa INT,\nIN p_dataInicio DATETIME,\nIN p_dataFim    DATETIME\n)\nBEGIN\n    SELECT\n        DATE_FORMAT(MIN(dthPedido), '%b/%y') AS mes,\n        COALESCE(SUM(valorTotal), 0)         AS faturamento,\n        COUNT(*)                             AS qtdPedidos\n    FROM Pedido\n    WHERE idEmpresa       = p_idEmpresa\n      AND statusPedido_id != 5\n      AND dthPedido BETWEEN p_dataInicio AND p_dataFim\n    GROUP BY YEAR(dthPedido), MONTH(dthPedido)\n    ORDER BY YEAR(dthPedido), MONTH(dthPedido);\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
